std::vector<Node> nodes;
nodes.reserve(rt.number_of_vertices());

for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
    const auto& point = vit->point();
    const auto& weight = vit->weight();
    const auto& handle = vit->handle();

    // Get position (weighted point)
    Node node;
    node.position = std::array<double, 3>{point.x(), point.y(), point.z()};

    // Get velocity (from associated info)
    if constexpr (std::is_same_v<typename RT::Vertex::Info, void>) {
        node.velocity = {0.0, 0.0, 0.0};
    } else {
        const auto& info = vit->info();
        node.velocity = std::array<double, 3>{info.vx, info.vy, info.vz};
    }

    // Get mass (from associated info or weight)
    if constexpr (std::is_same_v<typename RT::Vertex::Info, void>) {
        node.mass = weight;
    } else {
        node.mass = vit->info().mass;
    }

    // Classify node type based on incident edges
    int edge_count = 0;
    double min_edge_length = std::numeric_limits<double>::max();
    for (auto eit = rt.incident_edges(handle); eit != RT::Edge_iterator(); ++eit) {
        if (!rt.is_infinite(eit)) {
            auto edge_length = std::sqrt(rt.segment(eit).squared_length());
            if (edge_length < min_edge_length) {
                min_edge_length = edge_length;
            }
            edge_count++;
        }
    }

    if (edge_count == 0) {
        node.type = Node::ISOLATED;
    } else if (min_edge_length > threshold) {
        node.type = Node::SURFACE;
    } else {
        node.type = Node::INTERIOR;
    }

    // Set time
    node.time = time;

    nodes.push_back(node);
}

return nodes;
// END_CODE

